const body = $json.body || $json;
const idConsulta = body.id_consulta || body.idConsulta;
const pregunta = (body.pregunta || '').trim();
const nivel = body.nivel_experiencia || body.nivelExperiencia || 'No especificado';
const area = body.area_interes || body.areaInteres || 'General';
const cursosPrevios = body.cursos_previos || body.cursosPrevios || [];
const contextoPrevio = body.contexto_previo || body.contextoPrevio || '';
const umbral = (body.umbral !== undefined && body.umbral !== null) ? Number(body.umbral) : 0.40;

if (!pregunta) {
  throw new Error('La pregunta no puede estar vacía');
}

return {
  json: {
    id_consulta: idConsulta,
    pregunta: pregunta,
    pregunta_embedding: pregunta,
    nivel_experiencia: nivel,
    area_interes: area,
    cursos_previos: cursosPrevios,
    contexto_previo: contextoPrevio,
    umbral: umbral
  }
};

const qdrantResp = $json.result || [];
const inputData = $('Validar Consulta').first().json;
const UMBRAL = (inputData.umbral !== undefined && inputData.umbral !== null) ? Number(inputData.umbral) : 0.40;

const p = (inputData.pregunta || '').toLowerCase().trim();

const esIdentidad = /^(que|qué)\s+(es|hace)\s+ruta\s*ia/i.test(p) || 
  /quien\s+(eres|es\s+ruta\s*ia)/i.test(p) || 
  /como\s+funciona\s+(esta\s+pagina|la\s+pagina|ruta\s*ia)/i.test(p) ||
  /de\s+que\s+trata\s+(esta\s+pagina|la\s+pagina|ruta\s*ia)/i.test(p) ||
  /que\s+es\s+esta\s+pagina/i.test(p);

const esCatalogo = /(dame|muestra|ver|mostrar|listar|lista|cuales\s+son|que|qué)\s+(la\s+lista\s+de\s+|el\s+)?(catalogo|catálogo|cursos\s+tienen|cursos\s+hay|cursos\s+disponibles|todos\s+los\s+cursos)/i.test(p) ||
  /^(cursos|catalogo|catálogo|lista\s+de\s+cursos)$/i.test(p) ||
  /que\s+cursos\s+(tienen|hay|ofrecen)/i.test(p) ||
  /dame\s+(la\s+)?lista/i.test(p);

if (esIdentidad) {
  const fuentes = (qdrantResp.slice(0, 3) || []).map(r => ({
    id: r.payload.curso_id || r.id,
    nombre: r.payload.nombre,
    descripcion: r.payload.descripcion,
    categoria: r.payload.categoria,
    nivel: r.payload.nivel,
    duracion_horas: r.payload.duracion_horas,
    similitud: 0.90
  }));
  const contextoTexto = fuentes.map((f, idx) => (
    `Curso representativo ${idx + 1}: ${f.nombre} (Categoría: ${f.categoria}, Nivel: ${f.nivel}) - ${f.descripcion}`
  )).join(String.fromCharCode(10) + String.fromCharCode(10));

  return {
    json: {
      id_consulta: inputData.id_consulta,
      pregunta: inputData.pregunta,
      nivel_experiencia: inputData.nivel_experiencia,
      area_interes: inputData.area_interes,
      cursos_previos: inputData.cursos_previos || [],
      contexto_previo: inputData.contexto_previo || '',
      contexto: contextoTexto,
      fuentes: fuentes,
      similitudes: fuentes.map(f => f.similitud),
      ejecutar_llm: true
    }
  };
}

if (esCatalogo) {
  const fuentes = (qdrantResp.slice(0, 5) || []).map(r => ({
    id: r.payload.curso_id || r.id,
    nombre: r.payload.nombre,
    descripcion: r.payload.descripcion,
    categoria: r.payload.categoria,
    nivel: r.payload.nivel,
    duracion_horas: r.payload.duracion_horas,
    similitud: Math.max(0.65, Math.round((r.score || 0.65) * 10000) / 10000)
  }));
  const contextoTexto = fuentes.map((f, idx) => (
    `Curso ${idx + 1}: ${f.nombre}
- Identificador: ${f.id}
- Categoría: ${f.categoria} | Nivel: ${f.nivel} | Duración: ${f.duracion_horas}h
- Descripción: ${f.descripcion}`
  )).join(String.fromCharCode(10) + String.fromCharCode(10));

  return {
    json: {
      id_consulta: inputData.id_consulta,
      pregunta: inputData.pregunta,
      nivel_experiencia: inputData.nivel_experiencia,
      area_interes: inputData.area_interes,
      cursos_previos: inputData.cursos_previos || [],
      contexto_previo: inputData.contexto_previo || '',
      contexto: contextoTexto,
      fuentes: fuentes,
      similitudes: fuentes.map(f => f.similitud),
      ejecutar_llm: true
    }
  };
}

// Filtrar por umbral de relevancia (RF 11)
const relevantes = qdrantResp.filter(item => (item.score || 0) >= UMBRAL);

if (relevantes.length === 0) {
  return {
    json: {
      id_consulta: inputData.id_consulta,
      pregunta: inputData.pregunta,
      respuesta: `No encontramos cursos en nuestro catálogo institucional que coincidan suficientemente con tu búsqueda ("${inputData.pregunta}"). Te invitamos a consultar el catálogo completo de tecnología o buscar términos relacionados con programación, desarrollo web, ciencia de datos, ciberseguridad o inteligencia artificial.`,
      fuentes: [],
      similitudes: [],
      estado_final: "Sin resultados",
      ejecutar_llm: false
    }
  };
}

// Construir fuentes normalizadas y contexto RAG (RF 12, RF 13)
let fuentes = relevantes.map(r => ({
  id: r.payload.curso_id || r.id,
  nombre: r.payload.nombre,
  descripcion: r.payload.descripcion,
  categoria: r.payload.categoria,
  nivel: r.payload.nivel,
  duracion_horas: r.payload.duracion_horas,
  similitud: Math.round(r.score * 10000) / 10000
}));

const nivelEst = (inputData.nivel_experiencia || '').toLowerCase();
fuentes.sort((a, b) => {
  let scoreA = a.similitud;
  let scoreB = b.similitud;
  if (nivelEst.includes('principi') || nivelEst.includes('basic')) {
    if (a.nivel === 'Principiante' || a.nivel === 'Básico') scoreA += 0.08;
    else if (a.nivel === 'Avanzado') scoreA -= 0.08;
    if (b.nivel === 'Principiante' || b.nivel === 'Básico') scoreB += 0.08;
    else if (b.nivel === 'Avanzado') scoreB -= 0.08;
  }
  return scoreB - scoreA;
});

const similitudes = fuentes.map(f => f.similitud);

const contextoTexto = fuentes.map((f, idx) => (
  `Curso ${idx + 1}: ${f.nombre}
- Identificador: ${f.id}
- Categoría: ${f.categoria} | Nivel: ${f.nivel} | Duración: ${f.duracion_horas} horas
- Similitud Semántica: ${(f.similitud * 100).toFixed(2)}%
- Descripción: ${f.descripcion}`
)).join(String.fromCharCode(10) + String.fromCharCode(10));

return {
  json: {
    id_consulta: inputData.id_consulta,
    pregunta: inputData.pregunta,
    nivel_experiencia: inputData.nivel_experiencia,
    area_interes: inputData.area_interes,
    cursos_previos: inputData.cursos_previos || [],
    contexto_previo: inputData.contexto_previo || '',
    contexto: contextoTexto,
    fuentes: fuentes,
    similitudes: similitudes,
    ejecutar_llm: true
  }
};

