const llmChoice = $json.choices && $json.choices[0] ? $json.choices[0].message.content : '';
const evaluacion = $('Evaluar Umbral y Contexto RAG').first().json;

let finalFuentes = [...evaluacion.fuentes];
if (llmChoice && finalFuentes.length > 1) {
  const chosenIndex = finalFuentes.findIndex(f => 
    llmChoice.toLowerCase().includes(f.nombre.toLowerCase()) ||
    (f.id && llmChoice.includes(`Identificador: ${f.id}`))
  );
  if (chosenIndex > 0) {
    const chosen = finalFuentes.splice(chosenIndex, 1)[0];
    finalFuentes.unshift(chosen);
  }
}

return {
  json: {
    id_consulta: evaluacion.id_consulta,
    pregunta: evaluacion.pregunta,
    respuesta: llmChoice || 'No se pudo generar la recomendación en este momento.',
    fuentes: finalFuentes,
    similitudes: finalFuentes.map(f => f.similitud),
    estado_final: 'Respondida'
  }
};
